#include <iostream>

int main() {
    int ch{0};
    int totalChars{0};

    // Read characters until EOF sentinel is encountered
    while ((ch = std::cin.get()) != EOF) {
        if (ch != '\n' && ch != '\r') {
            ++totalChars;
        }
    }

    std::cout << "Total non-newline characters read: " << totalChars << std::endl;
    return 0;
}

#include <iostream>

int main() {
    int aCount{0};
    int bCount{0};
    int otherCount{0};
    int grade{0};

    while ((grade = std::cin.get()) != EOF) {
        switch (grade) {
            case 'A':
            case 'a':
                ++aCount;
                break;
            case 'B':
            case 'b':
                ++bCount;
                break;
            case '\n':
            case '\t':
            case ' ':
            case '\r':
                break; // Ignore whitespace characters
            default:
                ++otherCount;
                break;
        }
    }

    std::cout << "A: " << aCount << "\n"
              << "B: " << bCount << "\n"
              << "Other: " << otherCount << std::endl;
    return 0;
}
